    /// <summary>
    /// Query session logs with optional filters.
    /// </summary>
    Task<SessionLogQueryResult> QueryAsync(
        string? agent = null,
        string? model = null,
        string? text = null,
        DateTimeOffset? from = null,
        DateTimeOffset? to = null,
        int limit = 100,
        int offset = 0,
